def runs_of(row):
    res=[]; i=0
    while i<len(row):
        j=i
        while j<len(row) and row[j]==row[i]: j+=1
        res.append((row[i],j-i,i,j-1))
        i=j
    return res
def f(g):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]
    for r in range(1,h,2):
        for c,(v,L,a,b) in enumerate(runs_of(g[r])):
            if c>=w-1: continue  # skip last column for now
            if L==1: continue    # interior singletons untouched
            # endpoint of a run of length>=2
            if (a==c or b==c) and v!=g[r][c]:  # placeholder
                pass
        # do it properly below
    for r in range(1,h,2):
        for c,(v,L,a,b) in enumerate(runs_of(g[r])):
            if w-1==c and v==0: o[r][c]=1  # edge singleton 0->1
            elif c<w-1 and L>=2 and (a==c or b==c):
                o[r][c]=1-v
    return o
